# -*- coding: utf-8 -*-
"""2026-10-29 daily: six Meta ad account pages modelled on the converting ad and agency pages."""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'dd29'))
from fams import *
F = 'ad'
META_HELP = 'Meta’s Business Help Center page on disabled or restricted ad accounts'

page('meta-ad-account-disabled-prepaid-balance', F, 'Disabled Meta Ad Account: What Happens to Prepaid Funds',
 'What happens to the prepaid balance on a disabled Meta ad account, the six-month window Meta describes, and what to do first.',
 'Your Meta ad account is disabled. What happens to the prepaid balance?', 'Prepaid balance on a disabled account',
 'Prepaid funds sit on the account while it is disabled. The clock that matters is how long it stays ineligible.',
 'A prepaid balance stays on a disabled ad account while the restriction is open. Meta says that if an account disabled for a policy violation stays ineligible for reinstatement for six months, unused prepaid funds may be forfeited where the law allows. So act early: read the notice, fix the cause and request a review.',
 [('Note the date', 'Write down the day the notice appeared. The six-month window counts from the restriction.'),
  ('Screenshot the balance', 'Save the billing page with the remaining prepaid amount and the account ID.'),
  ('Do not top up', 'Adding more funds to a disabled account does not help the review.')],
 [S('What Meta says about prepaid funds',
    'In %s, Meta explains that an ad account disabled for a policy violation that remains ineligible for reinstatement for six months may lose unused prepaid funds, where the law allows. After that point the account can no longer be reinstated. Meta does not publish more detail than this, so treat the six months as the outer limit, not a target.' % META_HELP),
  S('What to do in the first week',
    ol(['Open Business Support Home and select the disabled ad account to read the reason given.',
        'Check whether your own profile or the business portfolio is also restricted. If it is, that may be the real blocker.',
        'Fix anything that can be fixed: payment details, a landing page, business verification.',
        'Request a review as an admin, once, with clear and accurate details.',
        'Save every notice, decision and email with its date.'])),
  S('If the review is rejected',
    'A rejection does not always end things. Read the decision for another review option or a support route, and only go again with new information. See %s and %s.' % (A('/meta-ad-account-appeal-rejected-what-next/', 'what to do after a rejected appeal'), A('/disabled-ad-account-unpaid-balance/', 'what happens to an unpaid balance'))),
 ],
 [('Can I move the prepaid balance to another ad account?', 'Meta does not offer a self-serve transfer from a disabled account. Billing questions go through Meta’s own billing support.'),
  ('Does spending the balance on a new account help?', 'No. Running ads from a new account to get around a restriction can be treated as circumventing and make things worse.'),
  ('Who can request the review?', 'Meta says you must be an admin on the ad account to request a review.')],
 ['Advertisers with prepaid funds on a disabled account.', 'Agencies managing prepaid client accounts.', 'Small businesses with a prepaid campaign budget.'])

page('meta-support-chat-disabled-ad-account', F, 'Meta Support Chat for a Disabled Ad Account',
 'Can Meta support chat help with a disabled ad account? Where to find it, what it can and cannot do, and what to have ready.',
 'Can Meta support chat help with a disabled ad account?', 'Meta support chat for ad accounts',
 'Chat can explain a notice and point you to the right form. The review itself still runs through the account.',
 'Meta support chat can explain why an ad account was restricted and point you to the right review form, but the decision still comes from the review itself. Chat is not offered to every advertiser, and availability changes by account and region. Have the ad account ID, the notice and the dates ready before you start.',
 [('Start from the account', 'Open Business Support Home and pick the restricted account first.'),
  ('Have IDs ready', 'Ad account ID, business portfolio ID and the date of the notice.'),
  ('Keep a record', 'Copy or screenshot the chat before it closes.')],
 [S('Where support usually shows up',
    ul(['The Meta AI business assistant inside Business Support Home and Meta Business Suite.',
        'A chat or email option on the help pages, when your account is eligible.',
        'Messages in your Support Inbox or email after a review request.'])),
  S('What chat can and cannot do',
    'A support agent can tell you which asset is restricted, what the policy name means and whether a review is still open. Agents do not usually reverse a decision in the chat. If someone tells you chat staff can be paid to switch an account back on, that is a scam.'),
  S('Getting the most from one chat',
    ol(['Say which asset is affected: the ad account, your profile or the business portfolio.',
        'Paste the exact wording of the notice.',
        'Ask one clear question, such as whether another review is possible.',
        'Note the name or reference the agent gives you.'])),
 ],
 [('Why do I not see a chat option?', 'Chat is not offered to every account. Use Business Support Home and the review request instead.'),
  ('Does Meta Verified give better support?', 'It can add support access for some accounts. It does not change the review decision.'),
  ('Is a chat transcript useful later?', 'Yes. It shows what you were told and when, which helps if you need to explain the history.')],
 ['Advertisers who cannot find a human at Meta.', 'Agencies chasing a client account.', 'Anyone who wants to know what a notice means before appealing.'])

page('ad-account-disabled-mid-campaign-first-steps', F, 'Ad Account Disabled Mid-Campaign: First Steps',
 'Meta ad account disabled while campaigns were live? The first steps to protect the rest of your accounts and prepare a clean appeal.',
 'Ad account disabled while campaigns were running?', 'Disabled mid-campaign',
 'The first hour decides how much else gets pulled in. Contain first, appeal second.',
 'When an ad account is disabled mid-campaign, ads stop and spend pauses on that account. Do not open a new account to keep the campaign going. Check whether your profile and business portfolio are also restricted, pause launches on related accounts, save the notice and the last ads, then request one review with accurate details.',
 [('Do not rebuild elsewhere', 'Moving the same campaign to a new account is the most common way a single restriction spreads.'),
  ('Check the wider set', 'Your profile, the portfolio and any shared pages or pixels.'),
  ('Save the last ads', 'Screenshots of the active ads and landing pages at the time of the notice.')],
 [S('The first hour',
    ol(['Read the notice in Business Support Home and note which asset it names.',
        'Check the status of your own profile and the business portfolio.',
        'Pause new launches on other accounts that share the same page, card, domain or pixel.',
        'Screenshot the last ads, the landing pages and the billing page.',
        'Tell your team or client what happened in plain words.'])),
  S('What usually sits behind it',
    ul(['An ad or landing page that matched a policy flag.', 'A payment that failed or a card that was changed.',
        'A sharp jump in daily spend.', 'A new admin or a login from an unusual place.'])),
  S('Then the appeal',
    'Fix what is clearly out of line, then request a review as an admin. Keep it short and factual. See %s and %s.' % (A('/meta-ad-account-appeal-what-to-write/', 'what to write in an appeal'), A('/how-long-does-meta-ad-account-review-take/', 'how long a review takes'))),
 ],
 [('Will my other ad accounts be affected?', 'They can be if they share the same profile, portfolio, card or domain. That is why containment comes first.'),
  ('Should I tell the client straight away?', 'Yes. A short, honest update is better than silence. See the agency templates linked below.'),
  ('Can I keep the page running organically?', 'Usually yes. A restricted ad account does not by itself stop posting on the page.')],
 ['Media buyers and in-house ad teams.', 'Agencies with live client campaigns.', 'Shops in a busy sales period.'])

page('new-meta-ad-account-disabled-before-first-ad', F, 'New Meta Ad Account Disabled Before the First Ad',
 'Brand-new Meta ad account disabled before you ran a single ad? Why it happens, what to check and how to request a review.',
 'New Meta ad account disabled before your first ad?', 'Disabled before the first ad',
 'New accounts get extra checks. A restriction before any ad runs usually points to the profile, payment or setup.',
 'A new Meta ad account disabled before any ad ran is usually flagged by account signals, not ad content: a new or restricted personal profile, a card or billing country that does not fit, many accounts created at once, or a past restriction linked to you. Check your profile status first, then request a review.',
 [('Check your own profile', 'If your personal profile is restricted from advertising, every new account inherits it.'),
  ('Match payment and country', 'Card, billing country and business address should fit together.'),
  ('Stop creating accounts', 'Each new account made after a restriction adds to the problem.')],
 [S('Common triggers',
    ul(['A personal profile that is new, has little history or has its own restriction.',
        'A card that failed, belongs to someone else or was used on a restricted account.',
        'Several ad accounts or portfolios created in a short time.',
        'A link to an earlier restricted account through the same page, domain or device.'])),
  S('What to do',
    ol(['Open Business Support Home and check your profile as well as the ad account.',
        'Complete any identity or security step that is shown.',
        'Correct payment and business details so they match.',
        'Request a review once, as an admin, and wait for the decision before doing anything else.'])),
  S('What not to do',
    'Do not open more accounts or ask a friend to run the ads for you. Meta treats that as getting around a restriction. See %s and %s.' % (A('/can-i-make-a-new-ad-account-after-ban/', 'making a new ad account after a ban'), A('/ad-account-disabled-circumventing-systems-help/', 'circumventing systems help'))),
 ],
 [('Can a new account be disabled by mistake?', 'Yes. Automated checks are strict on new accounts, and some decisions are reversed after a review.'),
  ('Should I verify my business first?', 'Business verification helps with trust. It does not lift a restriction on its own.'),
  ('Does the card brand matter?', 'What matters is that the card works, belongs to you or the business, and fits the billing country.')],
 ['New advertisers setting up for the first time.', 'Small businesses opening their first ad account.', 'Freelancers setting up accounts for a client.'])

page('agency-business-portfolio-restricted-client-accounts', F, 'Agency Business Portfolio Restricted: Client Accounts',
 'Your agency business portfolio is restricted and client ad accounts are affected. How to contain it, who should appeal, and what to tell clients.',
 'Your agency business portfolio is restricted. What about client accounts?', 'Agency portfolio restricted',
 'When the agency portfolio goes down, every client connected to it can feel it. Sort the assets before you appeal.',
 'If your agency business portfolio is restricted, client ad accounts shared with it may stop delivering even when the client’s own assets are fine. List which assets sit in your portfolio and which belong to clients, appeal the portfolio from an admin profile, and let each client’s own admin handle any client-owned account.',
 [('Map the assets', 'Which ad accounts, pages and pixels are owned by you, and which are only shared.'),
  ('Appeal the right thing', 'The portfolio restriction is appealed by your admins. Client-owned accounts by theirs.'),
  ('Keep clients calm', 'A short update now saves a harder conversation later.')],
 [S('Owned or shared',
    'Client accounts that the client owns and only shares with you usually stay under the client’s control. Accounts created inside your portfolio are yours, and a portfolio restriction reaches them directly. Knowing which is which decides who files what.'),
  S('Containment for agencies',
    ol(['Check every admin profile in the portfolio for its own restriction.',
        'Pause new client onboarding and new ad accounts until the review is decided.',
        'Remove access for anyone who no longer needs it.',
        'Ask clients to check their own portfolio status.'])),
  S('Working with Unbanz on it',
    'Agencies can hand the portfolio and the affected client accounts to Unbanz under their own brand. Your clients deal only with you. See %s and %s.' % (A('/white-label-meta-ad-account-recovery-media-buyers/', 'white label recovery for media buyers'), A('/how-to-tell-client-account-disabled-template/', 'how to tell a client their account is disabled'))),
 ],
 [('Will my clients know Unbanz is involved?', 'No. In white label work your agency stays the contact, and Unbanz works behind it.'),
  ('Should clients appeal their own accounts?', 'If they own the account and it carries its own restriction, yes. Their admin has to request it.'),
  ('Can we move client accounts out of our portfolio?', 'Client-owned accounts can be unshared. Accounts created in your portfolio cannot simply be moved while it is restricted.')],
 ['Marketing and media buying agencies.', 'Freelance media buyers with client accounts.', 'In-house teams that manage several brands.'], audience='Marketing agencies')

page('meta-ad-account-restricted-after-sharing-access-with-freelancer', F, 'Ad Account Restricted After Adding a Freelancer',
 'Meta ad account restricted after giving a freelancer or new agency access? Why it happens and how to remove risk and appeal.',
 'Ad account restricted after giving a freelancer access?', 'Restricted after adding a freelancer',
 'A new person with access brings their own history. If their profile is flagged, your account can be reviewed too.',
 'If your ad account was restricted soon after you gave a freelancer or new agency access, their profile may carry a restriction or their logins may look unusual. Remove access you do not need, check every admin and agency with access in Business Settings, secure your own profile with two-factor, then request one review as an admin.',
 [('Review who has access', 'People, agencies and system users in Business Settings.'),
  ('Remove what is not needed', 'Cut access first. You can add it back later.'),
  ('Secure your profile', 'Two-factor on every admin profile.')],
 [S('Why this happens',
    ul(['The freelancer’s own profile is restricted from advertising.',
        'They log in from many countries or devices for many clients.',
        'They reused a card, page or domain linked to an earlier restriction.',
        'They launched ads that broke a policy on your account.'])),
  S('What to do',
    ol(['Open Business Support Home and read which asset is named.',
        'Remove the freelancer or agency while you check.',
        'Ask them, politely, whether their profile has a restriction.',
        'Request a review with accurate details about who manages the account.'])),
  S('Before you hire the next one',
    'Give the least access needed, ask whether their profile has had restrictions, and keep ownership of the ad account and pixel in your own portfolio. See %s.' % A('/ad-account-restricted-after-agency-shared-access/', 'restricted after sharing access with an agency')),
 ],
 [('Can I get the freelancer’s restriction lifted?', 'Only they can appeal their own profile. You appeal the assets you own.'),
  ('Will removing them clear the restriction?', 'Not by itself. It removes ongoing risk, and you still need a review.'),
  ('Should I give a freelancer admin access?', 'Usually not. Advertiser access is enough for most campaign work.')],
 ['Small businesses working with freelancers.', 'Brands changing agencies.', 'Founders running their own ad accounts.'])
